1	export type Cell = [number, number];
2	
3	const NEIGHBOR_OFFSETS: ReadonlyArray<Cell> = [
4	  [-1, -1], [-1, 0], [-1, 1],
5	  [ 0, -1],          [ 0, 1],
6	  [ 1, -1], [ 1, 0], [ 1, 1],
7	];
8	
9	const cellKey = ([x, y]: Cell): string => `${x},${y}`;
10	
11	const survivesWithNeighborCount = (count: number): boolean =>
12	  count === 2 || count === 3;
13	
14	const isBornWithNeighborCount = (count: number): boolean => count === 3;
15	
16	const neighborsOf = ([x, y]: Cell): Cell[] =>
17	  NEIGHBOR_OFFSETS.map(([dx, dy]) => [x + dx, y + dy]);
18	
19	const uniqueCells = (cells: Cell[]): Cell[] =>
20	  [...new Map(cells.map((c) => [cellKey(c), c])).values()];
21	
22	export function nextGeneration(cells: Cell[]): Cell[] {
23	  const aliveKeys = new Set(cells.map(cellKey));
24	  const isAlive = (cell: Cell): boolean => aliveKeys.has(cellKey(cell));
25	  const aliveNeighborCount = (cell: Cell): number =>
26	    neighborsOf(cell).filter(isAlive).length;
27	
28	  const survivors = cells.filter((cell) =>
29	    survivesWithNeighborCount(aliveNeighborCount(cell)),
30	  );
31	
32	  const births = uniqueCells(cells.flatMap(neighborsOf))
33	    .filter((cell) => !isAlive(cell))
34	    .filter((cell) => isBornWithNeighborCount(aliveNeighborCount(cell)));
35	
36	  return [...survivors, ...births];
37	}
