1	import { describe, it, expect } from "vitest";
2	import { nextGeneration, type Cell } from "./game-of-life.js";
3	
4	describe("Game of Life - nextGeneration", () => {
5	  it("single cell dies from underpopulation — [(0,0)] → []", () => {
6	    expect(nextGeneration([[0, 0]])).toEqual([]);
7	  });
8	  it("two adjacent cells die from underpopulation — [(0,1), (1,1)] → []", () => {
9	    expect(nextGeneration([[0, 1], [1, 1]])).toEqual([]);
10	  });
11	  it("block still life survives unchanged — [(0,0), (1,0), (0,1), (1,1)] → same", () => {
12	    const cells: Cell[] = [[0, 0], [1, 0], [0, 1], [1, 1]];
13	    const result = nextGeneration(cells);
14	    expect(result.sort()).toEqual(cells.sort());
15	  });
16	  it("live cell with 2 neighbors survives (rule 2)", () => {
17	    // diagonal: (0,0), (1,1), (2,2) — middle (1,1) has 2 neighbors
18	    const result = nextGeneration([[0, 0], [1, 1], [2, 2]]);
19	    expect(result).toContainEqual([1, 1]);
20	  });
21	  it("live cell with 3 neighbors survives (rule 2) — center of row+cell pattern survives", () => {
22	    // (0,0),(1,0),(2,0) row + (1,1) alive. Cell (1,1) has 3 live neighbors (0,0),(1,0),(2,0).
23	    const result = nextGeneration([[0, 0], [1, 0], [2, 0], [1, 1]]);
24	    expect(result).toContainEqual([1, 1]);
25	  });
26	  it("live cell with 4 neighbors dies from overpopulation (rule 3)", () => {
27	    // Center (1,1) with 4 diagonal neighbors: (0,0),(2,0),(0,2),(2,2)
28	    const result = nextGeneration([[1, 1], [0, 0], [2, 0], [0, 2], [2, 2]]);
29	    expect(result).not.toContainEqual([1, 1]);
30	  });
31	  it("dead cell with exactly 3 neighbors becomes alive (rule 4) — L-shape produces (1,1)", () => {
32	    // ##. / #.. / ... → dead (1,1) has neighbors (0,0),(1,0),(0,1) = 3 → born
33	    const result = nextGeneration([[0, 0], [1, 0], [0, 1]]);
34	    expect(result).toContainEqual([1, 1]);
35	  });
